mapper.select:
select ltcr.id, ltcr.platform_type as platformType, ltcr.logistics_supplier_id as logisticsSupplierId, ltcr.logistics_supplier_name as logisticsSupplierName, ltcr.logistics_channel_id as logisticsChannelId, ltcr.logistics_channel_name as logisticsChannelName, ltcr.logistics_channel_code as logisticsChannelCode, ltcr.third_supplier_code as thirdSupplierCode, ltcr.third_supplier_name as thirdSupplierName, ltcr.third_channel_code as thirdChannelCode, ltcr.third_channel_name as thirdChannelName, ltcr.is_push_mobile as isPushMobile, ltcr.push_type as pushType, ltcr.create_user_name as createUserName, ltcr.disabled as disabled, ltcrd.id as detailId, ltcrd.shop_id as shopId, ltcrd.shop_name as shopName, ltcrd.dict_platform as dictPlatform, case when ltcr.push_type = 'sender' or ltcr.push_type = 'receiver' or ltcr.push_type = 'orderReceiver' then '' else ltcrd.mobile end as mobile from logistics_third_channel_ref ltcr left join logistics_third_channel_ref_detail ltcrd on ltcr.id = ltcrd.main_id and ltcrd.is_deleted = false
${params.sqlMap.default} and ltcr.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ltcr.create_time desc
